package nextcloudimport

import (
	"fmt"
	"html"
	"io"
	"net/http"
	"net/http/httptest"
	"net/url"
	"regexp"
	"sort"
	"strings"
	"sync"
	"testing"
	"time"

	"git.danvics.com/danvics/soloclef/soloclef_connectors/nextcloud"
)

// node is one file or folder of the stand-in Nextcloud.
type node struct {
	folder  bool
	content string
	// size, when set, is a file of that many generated bytes instead of
	// content: a large download that the test never holds either.
	size int64
	etag string
	// noSize leaves the length out of the listing, as a server may.
	noSize bool
}

// cloud is a WebDAV server holding one account's files: enough of Nextcloud
// for the client to be tested against real HTTP. It answers PROPFIND at
// depth 0 and 1 and GET, checks the app password, and records what it was
// asked.
type cloud struct {
	t      testing.TB
	server *httptest.Server
	mu     sync.Mutex
	files  map[string]node
	// asked is every request, as "METHOD path".
	asked []string
	// before, when set, may answer a request itself; it returns true if it
	// did.
	before func(response http.ResponseWriter, request *http.Request) bool
	// sawAuth is the user names requests arrived with.
	sawAuth []string
	// searches is the body of every SEARCH.
	searches []string
}

const (
	cloudUser     = "ada"
	cloudLogin    = "ada@example.org"
	cloudPassword = "app-password"
)

func newCloud(t testing.TB, files map[string]node) *cloud {
	t.Helper()
	c := &cloud{t: t, files: files}
	c.server = httptest.NewServer(http.HandlerFunc(c.serve))
	t.Cleanup(c.server.Close)
	return c
}

func (c *cloud) account() Account {
	return Account{BaseURL: c.server.URL, Username: cloudUser, LoginName: cloudLogin, AppPassword: cloudPassword}
}

// quick is timings short enough for a test to wait out.
var quick = nextcloud.Timing{Listing: 5 * time.Second, Stall: 2 * time.Second, MaxRetryWait: 20 * time.Millisecond}

func (c *cloud) client() *nextcloud.Client {
	return nextcloud.NewClient(c.account(), c.server.Client().Transport, quick)
}

func (c *cloud) requests() []string {
	c.mu.Lock()
	defer c.mu.Unlock()
	return append([]string(nil), c.asked...)
}

func (c *cloud) serve(response http.ResponseWriter, request *http.Request) {
	const prefix = "/remote.php/dav/files/" + cloudUser
	if request.Method == "SEARCH" {
		c.search(response, request)
		return
	}
	path, err := url.PathUnescape(strings.TrimPrefix(request.URL.EscapedPath(), prefix))
	if err != nil || !strings.HasPrefix(request.URL.Path, prefix) {
		http.NotFound(response, request)
		return
	}
	if path = "/" + strings.Trim(path, "/"); path == "//" {
		path = "/"
	}
	user, password, _ := request.BasicAuth()
	c.mu.Lock()
	c.asked = append(c.asked, request.Method+" "+path)
	c.sawAuth = append(c.sawAuth, user)
	before := c.before
	held, found := c.files[path]
	c.mu.Unlock()

	if before != nil && before(response, request) {
		return
	}
	if user != cloudLogin || password != cloudPassword {
		response.WriteHeader(http.StatusUnauthorized)
		return
	}
	if path == "/" {
		held, found = node{folder: true}, true
	}
	if !found {
		http.NotFound(response, request)
		return
	}
	switch request.Method {
	case "PROPFIND":
		listed := []string{path}
		if request.Header.Get("Depth") == "1" && held.folder {
			c.mu.Lock()
			for candidate := range c.files {
				if candidate != path && nextcloud.ParentOf(candidate) == path {
					listed = append(listed, candidate)
				}
			}
			c.mu.Unlock()
			sort.Strings(listed[1:])
		}
		var body strings.Builder
		body.WriteString(`<?xml version="1.0"?><d:multistatus xmlns:d="DAV:" xmlns:oc="http://owncloud.org/ns">`)
		for _, each := range listed {
			c.mu.Lock()
			described := c.files[each]
			c.mu.Unlock()
			if each == "/" {
				described = node{folder: true}
			}
			body.WriteString(describe(prefix, each, described))
		}
		body.WriteString(`</d:multistatus>`)
		response.Header().Set("Content-Type", "application/xml")
		response.WriteHeader(http.StatusMultiStatus)
		_, _ = io.WriteString(response, body.String())
	case http.MethodGet:
		if held.folder {
			response.WriteHeader(http.StatusMethodNotAllowed)
			return
		}
		if held.size > 0 {
			_, _ = io.Copy(response, &generated{left: held.size})
			return
		}
		_, _ = io.WriteString(response, held.content)
	default:
		// The client is read-only; anything else is a bug in it.
		c.t.Errorf("the client sent %s", request.Method)
		response.WriteHeader(http.StatusMethodNotAllowed)
	}
}

// searchLiteral is the pattern of a SEARCH request's `like`.
var searchLiteral = regexp.MustCompile(`<d:literal>([^<]*)</d:literal>`)

// search answers a WebDAV SEARCH the way Nextcloud does: at the DAV root,
// for the account in the scope, every file and folder whose name contains
// the pattern's text without regard to case, and the scope itself first
// (which a client must leave out).
func (c *cloud) search(response http.ResponseWriter, request *http.Request) {
	const prefix = "/remote.php/dav/files/" + cloudUser
	user, password, _ := request.BasicAuth()
	raw, _ := io.ReadAll(request.Body)
	c.mu.Lock()
	c.asked = append(c.asked, "SEARCH "+request.URL.Path)
	c.searches = append(c.searches, string(raw))
	c.mu.Unlock()
	if user != cloudLogin || password != cloudPassword {
		response.WriteHeader(http.StatusUnauthorized)
		return
	}
	found := searchLiteral.FindStringSubmatch(string(raw))
	if request.URL.Path != "/remote.php/dav/" || found == nil || !strings.Contains(string(raw), "<d:href>/files/"+cloudUser+"</d:href>") {
		response.WriteHeader(http.StatusBadRequest)
		return
	}
	term := strings.ToLower(strings.Trim(html.UnescapeString(found[1]), "%"))
	var body strings.Builder
	body.WriteString(`<?xml version="1.0"?><d:multistatus xmlns:d="DAV:" xmlns:oc="http://owncloud.org/ns">`)
	body.WriteString(describe(prefix, "/", node{folder: true}))
	c.mu.Lock()
	paths := make([]string, 0, len(c.files))
	for path := range c.files {
		paths = append(paths, path)
	}
	// Against the order a client must impose: by path, files and folders
	// mixed.
	sort.Sort(sort.Reverse(sort.StringSlice(paths)))
	for _, path := range paths {
		parts := nextcloud.PathParts(path)
		if strings.Contains(strings.ToLower(parts[len(parts)-1]), term) {
			body.WriteString(describe(prefix, path, c.files[path]))
		}
	}
	c.mu.Unlock()
	body.WriteString(`</d:multistatus>`)
	response.Header().Set("Content-Type", "application/xml")
	response.WriteHeader(http.StatusMultiStatus)
	_, _ = io.WriteString(response, body.String())
}

// describe is one <d:response>, written the way Nextcloud writes one: the
// properties it has under a 200 propstat, the ones it lacks under a 404.
func describe(prefix, path string, held node) string {
	segments := nextcloud.PathParts(path)
	for index, segment := range segments {
		segments[index] = url.PathEscape(segment)
	}
	// "&" is legal in a URL path and not in XML text.
	href := strings.ReplaceAll(prefix+"/"+strings.Join(segments, "/"), "&", "&amp;")
	if held.folder && path != "/" {
		href += "/"
	}
	if held.folder {
		return `<d:response><d:href>` + href + `</d:href><d:propstat><d:prop>` +
			`<d:resourcetype><d:collection/></d:resourcetype><d:getlastmodified>Tue, 03 Feb 2026 04:05:06 GMT</d:getlastmodified>` +
			`<d:getetag>"folder-etag"</d:getetag><oc:size>4096</oc:size></d:prop><d:status>HTTP/1.1 200 OK</d:status></d:propstat>` +
			`<d:propstat><d:prop><d:getcontentlength/><d:getcontenttype/></d:prop><d:status>HTTP/1.1 404 Not Found</d:status></d:propstat></d:response>`
	}
	length := int64(len(held.content))
	if held.size > 0 {
		length = held.size
	}
	size := fmt.Sprintf(`<d:getcontentlength>%d</d:getcontentlength>`, length)
	missing := ""
	if held.noSize {
		size, missing = "", `<d:propstat><d:prop><d:getcontentlength/></d:prop><d:status>HTTP/1.1 404 Not Found</d:status></d:propstat>`
	}
	etag := held.etag
	if etag == "" {
		etag = "etag-of-" + strings.ReplaceAll(path, "&", "and")
	}
	return `<d:response><d:href>` + href + `</d:href><d:propstat><d:prop><d:resourcetype/>` + size +
		`<d:getlastmodified>Tue, 03 Feb 2026 04:05:06 GMT</d:getlastmodified><d:getcontenttype>application/pdf</d:getcontenttype>` +
		`<d:getetag>&quot;` + etag + `&quot;</d:getetag></d:prop><d:status>HTTP/1.1 200 OK</d:status></d:propstat>` + missing + `</d:response>`
}

// generated yields `left` bytes of a repeating pattern without holding
// them.
type generated struct{ left int64 }

func (g *generated) Read(buffer []byte) (int, error) {
	if g.left == 0 {
		return 0, io.EOF
	}
	if int64(len(buffer)) > g.left {
		buffer = buffer[:g.left]
	}
	for index := range buffer {
		buffer[index] = byte('a' + index%26)
	}
	g.left -= int64(len(buffer))
	return len(buffer), nil
}
